<template>
  <div :class="$style.root">{{ crtTime }}</div>
</template>

<script>
class WebWorker {
  constructor(worker) {
    const code = worker.toString();
    const blob = new Blob([`(${code})()`]);
    return new Worker(URL.createObjectURL(blob));
  }
}

function work() {
  let timer = null;
  this.onmessage = (e) => {
    let { second, state } = e.data;
    if (state === "stop") {
      if (timer) {
        clearInterval(timer);
        timer = null;
      }
      return;
    } else if (state === "start") {
      if (!timer) {
        timer = setInterval(() => {
          this.postMessage(--second);
        }, 1000);
      }
    }
  };
}

export default {
  name: "timer-count-down",
  props: {
    minute: { type: Number, default: 1 },
  },
  data() {
    return {
      second: 60 * this.minute,
      worker: undefined,
    };
  },
  computed: {
    crtTime() {
      const { second } = this;
      const min = String(Math.floor(second / 60)).padStart(2, "0");
      const sec = String(second % 60).padStart(2, "0");
      return `${min}:${sec}`;
    },
  },
  watch: {
    minute(min) {
      this.worker.postMessage({ state: "stop" });
      this.second = 60 * min;
      this.worker.postMessage({
        state: "start",
        second: this.second,
      });
    },
  },
  created() {
    const worker = new WebWorker(work);

    worker.postMessage({
      state: "start",
      second: this.second,
    });

    worker.onmessage = (e) => {
      if (e.data < 0) {
        worker.postMessage({ state: "stop" });
        this.$emit("stop");
        return;
      }
      this.second = e.data;
    };

    this.$on("hook:beforeDestroy", () => {
        worker.postMessage({ state: "stop" });
    });

    this.worker = worker;
  },
};
</script>

<style module>
.root {
}
</style>
